<template>
    <section v-if="flat && flatItems.length" class="cy-day-group" :class="{ 'cy-list-simple': prefs.view === 'simple' }">
        <div class="cy-day-card">
            <f7-link v-for="item in flatItems" :key="item.id" class="cy-entry" :class="{ 'cy-entry-selected': selectedIds.includes(item.id) }" :href="selectionMode ? '#' : entryLink(item)" @click="onClick($event, item)" @taphold="emit('hold', item)">
                <span v-if="selectionMode" class="cy-select-bill" :aria-label="selectedIds.includes(item.id) ? '已选择' : '未选择'"><f7-icon :f7="selectedIds.includes(item.id) ? 'checkmark_circle_fill' : 'circle'" /></span>
                <span v-else class="cy-entry-icon" aria-hidden="true" :style="!prefs.lineIcons && item.color ? { color: '#'+item.color } : undefined"><ItemIcon v-if="item.icon && item.type !== 4 && !item.investment" :icon-type="getCategoryIconType(item.iconType)" :icon-id="item.icon" /><f7-icon v-else :f7="item.investment ? 'chart_bar' : item.type === 4 ? transferIcon(item) : item.type === 1 ? prefs.specialIcons['adjustment'] : item.type === 2 ? 'money_dollar_circle' : 'cart'" /></span>
                <span class="cy-entry-copy"><span class="cy-entry-title"><strong>{{ title(item) }}</strong><small v-if="item.refundedAmount" class="cy-refund-badge">{{ item.hidden || accountView&&!assetAmountsVisible ? '已退款' : `退 ${ledgerMoney(item.refundedAmount, false)}` }}</small></span><span v-if="prefs.view === 'detail'" class="cy-entry-subline"><small v-for="tag in item.tags.slice(0, 2)" :key="tag" class="cy-entry-tag">{{ tag }}</small><small v-if="subtitle(item)" class="cy-entry-note">{{ subtitle(item) }}</small><f7-icon v-if="item.pictures?.length" class="cy-entry-picture" f7="photo" /></span><small class="cy-entry-time">{{ shortDay(item.day) }}{{ prefs.showTime ? ' ' + moment.unix(item.time).tz(scope.timeZone).format('HH:mm') : '' }}</small></span>
                <span class="cy-entry-value"><strong :class="item.type === 2 ? 'cy-income' : item.type === 3 ? 'cy-expense' : ''">{{ item.hidden || accountView&&!assetAmountsVisible ? '••••' : ledgerSignedAmount(item.amount, item.transferDirection ? item.transferDirection === 'in' ? 2 : 3 : item.type) }}<small v-if="item.currency !== 'CNY'">{{ item.currency }}</small></strong><small v-if="item.accountFee">{{ feeNote(item.accountFee, item.hidden || !assetAmountsVisible) }}</small><small v-if="item.originalAmount && !item.hidden && (!accountView||assetAmountsVisible)" class="cy-original-amount">{{ ledgerMoney(item.originalAmount, false) }}</small><small v-else-if="prefs.showOriginal && !item.hidden && (!accountView||assetAmountsVisible) && hasDiscount(item)" class="cy-original-amount">{{ ledgerMoney(new LedgerDecimal(item.amount).plus(item.discountAmount || '0').toString(), false) }}</small><small v-if="item.fxOriginal && !item.hidden && (!accountView||assetAmountsVisible)" class="cy-fx-original">原 {{ item.fxOriginal.currency === 'USD' ? '$' : item.fxOriginal.currency === 'CNY' ? '¥' : item.fxOriginal.currency }}{{ ledgerMoney(item.fxOriginal.amount, false) }}</small><small v-if="prefs.view === 'detail'" class="cy-entry-account"><ItemIcon v-if="prefs.showAccountIcon && item.accountIcon" :icon-type="getAccountIconType(item.accountIconType)" :icon-id="item.accountIcon" />{{ accountView ? item.bookName : item.account }}</small></span>
            </f7-link>
        </div>
    </section>
    <template v-else>
    <section v-for="group in groups" :key="group.day" class="cy-day-group" :class="{ 'cy-list-simple': prefs.view === 'simple' }">
        <header v-if="showHeading" class="cy-day-heading"><h2>{{ dayLabel(group.day) }}</h2><span><span>收 <b class="cy-income">{{ accountView&&!assetAmountsVisible?'••••':group.totals.complete?ledgerMoney(group.totals.income, false):'—' }}</b></span><span>支 <b class="cy-expense">{{ accountView&&!assetAmountsVisible?'••••':group.totals.complete?ledgerMoney(group.totals.expense, false):'—' }}</b></span><small v-if="!group.totals.complete">待换算</small></span></header>
        <div class="cy-day-card">
            <f7-link v-for="item in group.items" :key="item.id" class="cy-entry" :class="{ 'cy-entry-selected': selectedIds.includes(item.id) }" :href="selectionMode ? '#' : entryLink(item)" @click="onClick($event, item)" @taphold="emit('hold', item)">
                <span v-if="selectionMode" class="cy-select-bill" :aria-label="selectedIds.includes(item.id) ? '已选择' : '未选择'"><f7-icon :f7="selectedIds.includes(item.id) ? 'checkmark_circle_fill' : 'circle'" /></span>
                <span v-else class="cy-entry-icon" aria-hidden="true" :style="!prefs.lineIcons && item.color ? { color: '#'+item.color } : undefined"><ItemIcon v-if="item.icon && item.type !== 4 && !item.investment" :icon-type="getCategoryIconType(item.iconType)" :icon-id="item.icon" /><f7-icon v-else :f7="item.investment ? 'chart_bar' : item.type === 4 ? transferIcon(item) : item.type === 1 ? prefs.specialIcons['adjustment'] : item.type === 2 ? 'money_dollar_circle' : 'cart'" /></span>
                <span class="cy-entry-copy"><span class="cy-entry-title"><strong>{{ title(item) }}</strong><small v-if="item.refundedAmount" class="cy-refund-badge">{{ item.hidden || accountView&&!assetAmountsVisible ? '已退款' : `退 ${ledgerMoney(item.refundedAmount, false)}` }}</small></span><span v-if="prefs.view === 'detail'" class="cy-entry-subline"><small v-for="tag in item.tags.slice(0, 2)" :key="tag" class="cy-entry-tag">{{ tag }}</small><small v-if="subtitle(item)" class="cy-entry-note">{{ subtitle(item) }}</small><f7-icon v-if="item.pictures?.length" class="cy-entry-picture" f7="photo" /></span><small v-if="prefs.showTime" class="cy-entry-time">{{ moment.unix(item.time).tz(scope.timeZone).format('HH:mm') }}</small></span>
                <span class="cy-entry-value"><strong :class="item.type === 2 ? 'cy-income' : item.type === 3 ? 'cy-expense' : ''">{{ item.hidden || accountView&&!assetAmountsVisible ? '••••' : ledgerSignedAmount(item.amount, item.transferDirection ? item.transferDirection === 'in' ? 2 : 3 : item.type) }}<small v-if="item.currency !== 'CNY'">{{ item.currency }}</small></strong><small v-if="item.accountFee">{{ feeNote(item.accountFee, item.hidden || !assetAmountsVisible) }}</small><small v-if="item.originalAmount && !item.hidden && (!accountView||assetAmountsVisible)" class="cy-original-amount">{{ ledgerMoney(item.originalAmount, false) }}</small><small v-else-if="prefs.showOriginal && !item.hidden && (!accountView||assetAmountsVisible) && hasDiscount(item)" class="cy-original-amount">{{ ledgerMoney(new LedgerDecimal(item.amount).plus(item.discountAmount || '0').toString(), false) }}</small><small v-if="item.fxOriginal && !item.hidden && (!accountView||assetAmountsVisible)" class="cy-fx-original">原 {{ item.fxOriginal.currency === 'USD' ? '$' : item.fxOriginal.currency === 'CNY' ? '¥' : item.fxOriginal.currency }}{{ ledgerMoney(item.fxOriginal.amount, false) }}</small><small v-if="prefs.view === 'detail'" class="cy-entry-account"><ItemIcon v-if="prefs.showAccountIcon && item.accountIcon" :icon-type="getAccountIconType(item.accountIconType)" :icon-id="item.accountIcon" />{{ accountView ? item.bookName : item.account }}</small></span>
            </f7-link>
        </div>
    </section>
    </template>
</template>
<script setup lang="ts">
import { computed } from 'vue';
import {assetAmountsVisible} from '@/lib/asset-visibility.ts';
import moment from 'moment-timezone';
import { ledgerMoney, ledgerTotals, ledgerSignedAmount, LedgerDecimal, type LedgerEntry } from '@/lib/mobile-ledger.ts';
import { groupAccountTransferFees, ledgerAccountFlowTotals } from '@/lib/ledger-display.ts';
import { useLedgerScopeStore } from '@/stores/ledgerScope.ts';
import { useLedgerExperienceStore } from '@/stores/ledgerExperience.ts';
import { getCategoryIconType, getAccountIconType } from '@/lib/icon.ts';
import ItemIcon from './ItemIcon.vue';
import {useAccountsStore} from '@/stores/account.ts';
import {inferDebtOperation} from '@/lib/ledger-debt.ts';
const props = withDefaults(defineProps<{ entries: LedgerEntry[]; showHeading?: boolean; flat?: boolean; accountView?: boolean; budgetView?: boolean; partialLastDay?: boolean; selectionMode?: boolean; selectedIds?: string[] }>(), { showHeading: true, flat: false, accountView: false, budgetView: false, partialLastDay: false, selectionMode: false, selectedIds: () => [] });
const emit = defineEmits<{ hold: [item: LedgerEntry]; select: [item: LedgerEntry] }>();
const scope = useLedgerScopeStore(), experience = useLedgerExperienceStore();
const accounts=useAccountsStore();
const flatItems = computed(() => props.accountView ? groupAccountTransferFees(props.entries) : props.entries);
function shortDay(day: string): string { const d = moment(day, 'YYYY-MM-DD'); return d.format(d.year() === moment(scope.currentDay).year() ? 'M月D日' : 'YYYY年M月D日'); }
function transferIcon(item:LedgerEntry){const operation=inferDebtOperation(accounts.allAccountsMap[item.accountId],accounts.allAccountsMap[item.destinationAccountId]);return prefs.value.specialIcons[operation==='repay'?'repayment':operation==='collect'?'lend':operation||'transfer'];}
const prefs = computed(() => experience.preferences);
const groups = computed(() => {
    const days = new Map<string, LedgerEntry[]>();
    for (const item of props.entries) { if (!days.has(item.day)) days.set(item.day, []); days.get(item.day)!.push(item); }
    return [...days].sort(([a], [b]) => b.localeCompare(a)).map(([day, rawItems], index) => { const items = props.accountView ? groupAccountTransferFees(rawItems) : rawItems; const totals = props.accountView ? ledgerAccountFlowTotals(items) : ledgerTotals(items, !props.budgetView); if (props.partialLastDay && index === days.size - 1) totals.complete = false; return { day, items, totals }; });
});
function feeNote(fee:string,hidden:boolean):string{const amount=new LedgerDecimal(fee);return `${amount.lt(0)?'优惠':'手续费'}：${hidden?'••••':(amount.lt(0)?'+':'-')+ledgerMoney(amount.abs().toString(),false)}`;}
function category(item: LedgerEntry): string { if(item.investment)return item.title; if(item.type===1)return '余额调整'; return !prefs.value.simpleCategory && item.primaryCategory && item.primaryCategory !== item.title ? `${item.primaryCategory}-${item.title}` : item.title; }
function title(item: LedgerEntry): string {
    if (!item.investment && prefs.value.remarkFirst && item.comment) return item.comment;
    if (props.accountView && item.type === 4 && !item.investment && !inferDebtOperation(accounts.allAccountsMap[item.accountId], accounts.allAccountsMap[item.destinationAccountId])) {
        if (item.transferDirection === 'out' && item.destinationAccount) return `转出到「${item.destinationAccount}」`;
        if (item.transferDirection === 'in' && item.sourceAccountName) return `从「${item.sourceAccountName}」转入`;
    }
    return category(item);
}
function subtitle(item: LedgerEntry): string { if(item.investment && ['投资买入','投资卖出'].includes(item.comment))return ''; return prefs.value.remarkFirst && item.comment ? category(item) : item.comment; }
function hasDiscount(item: LedgerEntry): boolean { return !!item.discountAmount && new LedgerDecimal(item.discountAmount).gt(0); }
function entryLink(item: LedgerEntry): string { if(item.refundId && item.refundExpenseId)return `/transaction/detail?id=${item.refundExpenseId}&type=3`; if(item.wallet)return `/transaction/detail?id=${item.id}&type=${item.type}`; if(item.transferFeeParentId && item.transferFeeParentId!=='0')return `/transaction/detail?id=${item.transferFeeParentId}&type=4`; return item.investmentEventId ? `/investments/record?action=revise&eventId=${encodeURIComponent(item.investmentEventId)}` : `/transaction/detail?id=${item.id}&type=${item.type}`; }
function onClick(event: MouseEvent, item: LedgerEntry) { if (props.selectionMode) { event.preventDefault(); event.stopPropagation(); emit('select', item); } }
function dayLabel(day: string): string {
    const date = moment(day, 'YYYY-MM-DD'), today = moment(scope.currentDay, 'YYYY-MM-DD');
    const relative = day === scope.currentDay ? '今天 ' : day === today.subtract(1, 'day').format('YYYY-MM-DD') ? '昨天 ' : '';
    return `${date.format(date.year()===moment(scope.currentDay).year()?'M月D日':'YYYY年M月D日')}  ${relative}${['周日','周一','周二','周三','周四','周五','周六'][date.day()]}`;
}
</script>
<style scoped>
.cy-day-group{margin-bottom:17px}.cy-day-heading{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:7px}.cy-day-heading h2{font-size:calc(13px * var(--cy-font-scale, 1));white-space:nowrap;font-weight:500}.cy-day-heading>span{display:flex;gap:12px;flex-wrap:wrap;justify-content:flex-end;font-size:calc(12px * var(--cy-font-scale, 1))}.cy-day-heading b{font-weight:500}.cy-day-heading small{color:var(--cy-muted)}.cy-day-card{border-radius:11px;background:var(--cy-card);padding:2px 10px;overflow:hidden}.cy-entry{display:flex;width:100%;gap:10px;padding:6px 0;color:var(--cy-ink);align-items:center;white-space:normal;box-sizing:border-box;min-height:55px}.cy-entry-icon{color:var(--cy-icon,#798582);flex:0 0 25px;display:grid;place-items:center}.cy-entry-icon :deep(.icon){font-size:24px;color:inherit!important;--ebk-icon-font-size:26px}.cy-entry-copy{flex:1;min-width:0;align-self:center}.cy-entry-title{display:flex;align-items:center;gap:5px;min-width:0}.cy-entry-copy strong{display:block;font-weight:400;font-size:calc(15px * var(--cy-font-scale, 1));line-height:1.5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cy-refund-badge{flex:none;background:#fbe9d9;color:#9d5a26;border-radius:5px;padding:1px 4px;font-size:calc(10px * var(--cy-font-scale, 1));line-height:1.5;white-space:nowrap}.cy-entry-subline{display:flex;align-items:center;gap:5px;margin-top:2px;min-width:0;overflow:hidden}.cy-entry-tag{display:block;max-width:118px;min-width:0;flex:0 1 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:var(--cy-soft);color:var(--cy-muted);border-radius:10px;padding:1px 5px;font-size:calc(10px * var(--cy-font-scale, 1));line-height:1.5}.cy-entry-note{min-width:0;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--cy-muted);font-size:calc(11px * var(--cy-font-scale, 1));line-height:1.7}.cy-entry-time{display:block;font-size:calc(10px * var(--cy-font-scale, 1));color:var(--cy-muted);margin-top:2px}.cy-entry-picture{font-size:12px;color:var(--cy-muted);flex:none}.cy-entry-value{text-align:right;max-width:45%;min-width:52px;flex-shrink:0}.cy-entry-value strong{font-size:calc(16px * var(--cy-font-scale, 1));font-weight:500;overflow-wrap:anywhere;line-height:1.5}.cy-entry-value strong small{display:inline;margin-left:3px;font-size:calc(10px * var(--cy-font-scale, 1))}.cy-entry-value small{display:block;font-size:calc(10px * var(--cy-font-scale, 1));color:var(--cy-muted);font-weight:400;line-height:1.7;margin-top:2px;overflow-wrap:anywhere}.cy-entry-account :deep(.icon){font-size:11px;--ebk-icon-font-size:12px;margin-right:4px;vertical-align:middle}.cy-original-amount{text-decoration:line-through}.cy-list-simple .cy-entry{min-height:44px;padding-block:8px}.cy-entry-selected{background:var(--cy-soft)}.cy-select-bill{color:var(--cy-accent);width:25px}.cy-select-bill .icon{font-size:22px;transition:transform 160ms var(--cy-ease-spring,cubic-bezier(0.34,1.56,0.64,1))}.cy-entry-selected .cy-select-bill .icon{transform:scale(1.08)}
</style>
